export const date = '2026-10-07';
export const guides = [
  {
    file: 'south-america-wall-panel-colour-sample-lighting.html', image: 'colour-sample-lighting-20261007.svg', product: '/products/fluted-wall-panels.html', catalog: '/assets/catalogs/dream-house-wall-panel-catalog.pdf', source: 'https://www.cie.co.at/publications/standard-method-assessing-spectral-quality-daylight-simulators-visual-appraisal-and-1', sourceName: 'CIE colour-appraisal standard', related: ['gulf-wall-panels-near-air-conditioning-diffusers.html', 'uzbekistan-spc-flooring-concrete-slab-moisture-check.html', 'reduce-wall-panel-batch-color-differences.html', 'evaluate-wall-panel-samples.html'],
    en: { title: 'Wall Panel Colour Samples: Lighting Checks | Luvie', description: 'A practical colour-approval checklist for South American wall panel distributors: compare physical samples in the intended lighting and record one signed reference.', heading: 'Why does a wall panel sample look different in the showroom?', lead: 'A warm showroom spotlight, daylight by the window and a buyer’s phone screen can make the same finish appear different. For distributors in South America, this becomes a purchasing problem when a sample approved online is compared with installed stock under a different light. The answer is a controlled physical approval, not a promise that every image will match.', answer: 'Compare the same physical sample under the lighting planned for the project, record the viewing conditions and approve one coded reference before ordering a batch.', sections: [
      ['Separate a visual reference from a production specification', 'A catalog PDF or web photograph is useful for narrowing a range, but screens, camera processing and lighting alter appearance. Ask for the exact product code, surface finish, profile and a physical sample. If two panels have similar names, confirm that they share the same construction and finish rather than assuming the catalog image is the specification. Keep the approved sample protected from scratches and sunlight while it is used for comparison.'],
      ['Use more than one relevant light', 'Review the sample in diffuse daylight and under the lighting actually planned for the store or project. The International Commission on Illumination (CIE) publishes a standard for assessing daylight simulators used in visual colour appraisal; its point for buyers is that the light source matters. This is general colour-science guidance, not a colour tolerance or certification for a Luvie panel. Avoid deciding from a phone photo taken under mixed lighting.'],
      ['Approve the sample next to trims and adjacent materials', 'Put the panel beside its corner trim, skirting, floor and paint sample. Check it at normal viewing distance and again at joints and cut edges. A small swatch can hide a pattern repeat or a visible transition across a larger wall. For a retail rollout, assemble a modest mock-up with the actual lamps, then record whether the design team accepts tone, sheen, texture direction and joint detail.'],
      ['Write a repeatable batch-approval record', 'Record sample code, date, finish, lighting location, viewing distance, approved trim and the person who signed off. When stock arrives, compare representative cartons with that reference before the installer mixes material across walls. If the proposed lot differs, pause and document the difference rather than selecting the closest-looking replacement without approval. Ask Luvie for current model-specific sampling and batch-identification details.']
    ], closing: 'Send the finish code, destination market and intended lighting to request a current physical sample and an approval checklist.' },
    es: { title: 'Muestras de color de paneles: revisión de luz | Luvie', description: 'Guía para distribuidores sudamericanos: compare muestras físicas con la iluminación prevista y registre una referencia aprobada para cada acabado.', heading: '¿Por qué cambia el aspecto de un panel entre la muestra y la tienda?', lead: 'Un foco cálido, la luz de la ventana y la pantalla del teléfono pueden mostrar el mismo acabado de manera distinta. Para un distribuidor, el problema surge cuando se aprueba una foto y luego se compara el lote instalado bajo otra luz. La solución es una aprobación física y documentada, no la promesa de que todas las imágenes coincidirán.', answer: 'Compare la misma muestra física con la iluminación del proyecto, registre las condiciones de observación y apruebe una referencia codificada antes de pedir el lote.', sections: [
      ['Distinga la imagen comercial de la especificación', 'El catálogo y la fotografía ayudan a elegir opciones, pero la cámara, la pantalla y la luz modifican la apariencia. Solicite código exacto, acabado superficial, perfil y muestra física. Dos paneles con nombres parecidos no necesariamente comparten construcción o acabado. Proteja la muestra aprobada de rayaduras y sol mientras sirva de referencia.'],
      ['Revise con más de una luz pertinente', 'Compare la muestra con luz diurna difusa y con las lámparas previstas para la tienda u obra. La Comisión Internacional de Iluminación (CIE) publica una norma sobre simuladores de luz diurna para evaluación visual del color: la fuente de luz influye en el examen. Es una referencia general, no una tolerancia ni certificación de un panel Luvie. No decida solo a partir de una foto con luces mezcladas.'],
      ['Incluya molduras y materiales vecinos', 'Coloque el panel junto a la moldura, el zócalo, el suelo y la pintura elegidos. Mírelo a distancia normal y de cerca en juntas y cortes. Una muestra pequeña puede ocultar repeticiones de dibujo o cambios visibles en un muro grande. Para varias tiendas, monte un tramo de prueba con las lámparas reales y confirme tono, brillo, textura y junta.'],
      ['Documente la aprobación del lote', 'Anote código, fecha, acabado, lugar e iluminación de revisión, distancia, moldura y responsable de aprobación. A la recepción compare cartones representativos con esa muestra antes de mezclar el material. Si hay diferencias, detenga la instalación y documente el caso. Pida a Luvie información actual del modelo sobre muestras e identificación de lotes.']
    ], closing: 'Envíe el código de acabado, el mercado de destino y la iluminación prevista para solicitar una muestra física actual.' },
    'pt-br': { title: 'Amostras de cor de painéis: confira a iluminação | Luvie', description: 'Guia para distribuidores: compare amostras físicas sob a iluminação prevista e registre uma referência aprovada antes do pedido.', heading: 'Por que o painel parece diferente na amostra e na loja?', lead: 'Um spot quente, a luz da janela e a tela do celular podem mostrar o mesmo acabamento de maneiras diferentes. O risco comercial aparece quando uma imagem é aprovada e o lote instalado é avaliado sob outra luz. A resposta é aprovar uma amostra física com registro, não prometer que todas as fotos serão iguais.', answer: 'Compare a mesma amostra física sob a iluminação do projeto, anote as condições de observação e aprove uma referência identificada antes do lote.', sections: [
      ['Separe foto comercial de especificação', 'Catálogo e fotografia ajudam a selecionar opções, mas câmera, tela e luz mudam a aparência. Peça código exato, acabamento, perfil e amostra física. Nomes parecidos não garantem construção ou acabamento iguais. Proteja a amostra aprovada contra riscos e sol enquanto ela for referência.'],
      ['Compare sob luzes relevantes', 'Avalie sob luz diurna difusa e sob as luminárias planejadas para a loja ou obra. A Comissão Internacional de Iluminação (CIE) publica um padrão para simuladores de luz diurna usados na avaliação visual de cores: a fonte luminosa importa. Trata-se de ciência geral, não de tolerância ou certificação de um painel Luvie. Evite decidir apenas por foto feita sob luz misturada.'],
      ['Inclua arremates e materiais vizinhos', 'Coloque o painel junto a cantoneira, rodapé, piso e tinta escolhidos. Observe à distância normal e de perto nas juntas e cortes. Uma peça pequena pode esconder repetição de desenho ou transição numa parede grande. Para várias lojas, monte um trecho de teste com as luminárias reais e aprove tom, brilho, textura e juntas.'],
      ['Registre a aprovação do lote', 'Anote código, data, acabamento, local e luz da avaliação, distância, arremate e responsável pelo aceite. No recebimento, compare caixas representativas com a amostra antes de misturar material. Se houver diferença, pause a instalação e documente. Solicite à Luvie informações atuais de amostragem e identificação de lotes do modelo.']
    ], closing: 'Envie código do acabamento, mercado de destino e iluminação prevista para solicitar uma amostra física atual.' },
    ar: { title: 'عينات ألوان ألواح الجدران: فحص الإضاءة | Luvie', description: 'دليل للموزعين لمقارنة العينات الفعلية تحت إضاءة المشروع وتوثيق مرجع معتمد للتشطيب قبل طلب الكمية.', heading: 'لماذا يبدو لون لوح الجدار مختلفاً بين العينة والمتجر؟', lead: 'قد يجعل المصباح الدافئ وضوء النافذة وشاشة الهاتف التشطيب نفسه يبدو مختلفاً. تظهر المشكلة التجارية عندما تُعتمد صورة ثم تُقارن الشحنة المركبة تحت إضاءة أخرى. الحل هو اعتماد عينة فعلية موثقة، لا الوعد بتطابق كل الصور.', answer: 'قارن العينة الفعلية تحت إضاءة المشروع، وسجّل ظروف الفحص، واعتمد مرجعاً برمز واضح قبل طلب الدفعة.', sections: [
      ['افصل الصورة التسويقية عن المواصفة', 'يساعد الكتالوج والصورة على اختيار البدائل، لكن الكاميرا والشاشة والضوء تغير المظهر. اطلب رمز المنتج والتشطيب وشكل المقطع وعينة فعلية. تشابه الأسماء لا يعني تطابق التركيب أو السطح. احم العينة المعتمدة من الخدش والشمس أثناء استخدامها مرجعاً.'],
      ['افحص تحت أكثر من إضاءة مناسبة', 'راجع العينة في ضوء نهاري منتشر وتحت مصابيح المتجر أو المشروع المقترحة. تنشر اللجنة الدولية للإضاءة CIE معياراً لمحاكيات ضوء النهار في التقييم البصري للألوان؛ لذلك يهم نوع مصدر الضوء. هذا مرجع علمي عام، وليس حد تفاوت أو شهادة للوح من Luvie. لا تعتمد على صورة هاتف تحت إضاءة مختلطة.'],
      ['ضع الزوايا والمواد المجاورة بجوار العينة', 'ضع اللوح بجوار زاوية التشطيب والوزرة والأرضية والطلاء المختار. افحصه من مسافة المشاهدة الطبيعية ثم عند الفواصل والحواف المقطوعة. قد تخفي العينة الصغيرة تكرار النقش أو انتقالاً ظاهراً على جدار كبير. في مشروع متاجر متعدد المواقع، أنشئ جزءاً تجريبياً بالمصابيح الفعلية واعتمد اللون واللمعان واتجاه الملمس والفواصل.'],
      ['وثّق اعتماد الدفعة', 'سجّل رمز العينة والتاريخ والتشطيب ومكان الفحص وإضاءته والمسافة والزوايا والشخص الذي وافق. عند وصول البضاعة قارن صناديق ممثلة بالمرجع قبل خلط الألواح في الجدار. إذا ظهر اختلاف، أوقف التركيب ووثّق الحالة. اطلب من Luvie معلومات الطراز الحالية عن العينات ورموز الدفعات.']
    ], closing: 'أرسل رمز التشطيب والسوق المقصود وإضاءة المشروع لطلب عينة فعلية حالية.' }
  },
  {
    file: 'gulf-wall-panels-near-air-conditioning-diffusers.html', image: 'gulf-airflow-wall-20261007.svg', product: '/products/wpc-wall-panels.html', catalog: '/assets/catalogs/wpc-collection-2026.pdf', source: 'https://www.epa.gov/indoor-air-quality-iaq/moisture-control-guidance-building-design-construction-and-maintenance-0', sourceName: 'U.S. EPA moisture-control guidance', related: ['south-america-wall-panel-colour-sample-lighting.html', 'uzbekistan-spc-flooring-concrete-slab-moisture-check.html', 'gulf-hotel-decorative-wall-condensation.html', 'pvc-wall-panels-coastal-humid-interiors.html'],
    en: { title: 'Wall Panels Near AC Diffusers: Gulf Fit-Out Checks | Luvie', description: 'For Gulf retail and hospitality fit-outs, assess air-conditioning, concealed moisture and service access before placing decorative wall panels near diffusers.', heading: 'Can decorative wall panels sit beside an AC diffuser in a Gulf fit-out?', lead: 'A feature wall beside an air-conditioning diffuser can be visually successful but difficult to maintain if condensation, leaks or service access were never considered. The decision is not whether one material name is “waterproof”; it is whether the designer has resolved the wall, air and maintenance details for the exact room.', answer: 'They may be used only after the project team checks airflow, condensation risk, substrate condition, clearances and access for the particular diffuser and panel system.', sections: [
      ['Find the source of moisture before choosing the face', 'Ask whether the wall is an exterior boundary, a cooled interior wall or a surface beside a condensate line. Review prior stains, smells and leaks. The U.S. EPA guidance treats moisture as a whole-building design and maintenance issue; it does not certify any decorative panel. A washable face must not conceal a wet wall or solve a leaking drain by itself.'],
      ['Draw the diffuser and panel in one detail', 'Mark the outlet, return path, nearby cold surfaces, joints, fixings and any removable access panel. Confirm that the decorative finish does not obstruct airflow or equipment access. The mechanical designer should review where humid air can encounter a cold surface and whether the intended assembly can dry. Do not copy a clearance from another project without the equipment instructions and local approval.'],
      ['Test the real finish under operating conditions', 'Request the exact panel code and current installation instructions. Build a small mock-up with a corner, trim and service opening. Observe it while the AC runs, then check the backing for moisture before closing the wall. Cleaning chemicals, attachment method and fire requirements should be checked separately for the specified SKU; a photograph cannot establish compliance.'],
      ['Write a maintenance handoff', 'Specify who inspects the diffuser, condensate drain and wall backing after occupancy, and how access can be opened without destroying the finish. Keep drawings, sample code and photos of the concealed assembly. For a hotel or shop chain, one approved detail should be tested on site before it is repeated across locations.']
    ], closing: 'Share the wall position, HVAC drawing and chosen sample so the design team can review a model-specific detail.' },
    es: { title: 'Paneles junto a difusores de aire: guía del Golfo | Luvie', description: 'En tiendas y hoteles del Golfo, revise aire acondicionado, humedad oculta y acceso técnico antes de colocar paneles junto a difusores.', heading: '¿Se pueden colocar paneles decorativos junto a un difusor de aire?', lead: 'Una pared decorativa junto al aire acondicionado puede verse bien y aun así ser difícil de mantener si no se estudiaron condensación, fugas y acceso técnico. La pregunta no es si un material se anuncia como «impermeable», sino si el equipo resolvió los detalles del muro, el aire y el mantenimiento para esa sala.', answer: 'Solo debe decidirse tras revisar flujo de aire, riesgo de condensación, soporte, separaciones y acceso para el difusor y sistema específicos.', sections: [
      ['Busque el origen de la humedad', 'Determine si se trata de muro exterior, pared interior enfriada o superficie junto a un desagüe de condensados. Revise manchas, olores y fugas previas. La guía de la EPA trata la humedad como cuestión de diseño y mantenimiento del edificio; no certifica paneles. Una cara lavable no corrige una pared mojada ni una tubería con fugas.'],
      ['Dibuje difusor y panel en un mismo detalle', 'Marque salida, retorno de aire, superficies frías, juntas, fijaciones y registro desmontable. Confirme que el acabado no obstaculice ventilación ni mantenimiento. El especialista mecánico debe evaluar dónde el aire húmedo puede encontrar una superficie fría y cómo secará el conjunto. No copie separaciones de otra obra sin consultar equipo y normativa local.'],
      ['Pruebe el acabado en condiciones reales', 'Pida código e instrucciones actuales del modelo. Monte una prueba con esquina, moldura y abertura de servicio. Obsérvela con el aire acondicionado funcionando y revise el soporte antes de cerrar el muro. Productos de limpieza, fijación y exigencias contra incendios se verifican por separado para el modelo exacto; una foto no demuestra cumplimiento.'],
      ['Deje instrucciones de mantenimiento', 'Indique quién revisará difusor, drenaje y trasera del muro y cómo abrir el registro sin destruir el acabado. Conserve planos, código de muestra y fotos de la instalación oculta. En una cadena de hoteles o tiendas, pruebe el detalle aprobado antes de repetirlo en todas las sedes.']
    ], closing: 'Comparta posición del muro, plano de climatización y muestra para revisar un detalle específico.' },
    'pt-br': { title: 'Painéis perto de difusores de ar: guia do Golfo | Luvie', description: 'Para lojas e hotéis no Golfo, avalie ar-condicionado, umidade oculta e acesso de manutenção antes de instalar painéis perto de difusores.', heading: 'Painéis decorativos podem ficar ao lado de um difusor de ar?', lead: 'Uma parede de destaque junto ao ar-condicionado pode ter boa aparência e ainda ser difícil de manter se condensação, vazamentos e acesso não foram considerados. A decisão não depende de um material ser anunciado como “à prova d’água”, mas do detalhe completo da parede, do ar e da manutenção naquela sala.', answer: 'A instalação depende de avaliação do fluxo de ar, condensação, base, afastamentos e acesso para o difusor e o sistema específicos.', sections: [
      ['Investigue a origem da umidade', 'Identifique parede externa, parede interna resfriada ou superfície próxima ao dreno de condensado. Procure manchas, odores e vazamentos antigos. A orientação da EPA trata umidade como questão de projeto e manutenção do edifício; não certifica painéis. Uma face lavável não conserta parede molhada nem dreno com defeito.'],
      ['Desenhe difusor e painel no mesmo detalhe', 'Marque saída, retorno do ar, superfícies frias, juntas, fixações e abertura removível. Confirme que o acabamento não bloqueia ventilação ou manutenção. O projetista mecânico deve avaliar onde ar úmido encontra superfícies frias e como o conjunto pode secar. Não copie afastamentos de outra obra sem instruções do equipamento e aprovação local.'],
      ['Teste o acabamento com o sistema operando', 'Peça código e instruções atuais do modelo. Monte um trecho com canto, arremate e acesso técnico. Observe com o ar-condicionado ligado e examine a base antes de fechar a parede. Limpeza, fixação e requisitos de incêndio exigem checagem separada para o SKU; foto não prova conformidade.'],
      ['Entregue um plano de manutenção', 'Defina quem verifica difusor, dreno e fundo da parede e como abrir o acesso sem destruir o acabamento. Guarde desenhos, código da amostra e fotos da montagem oculta. Numa rede de hotéis ou lojas, teste um detalhe aceito antes de repeti-lo em vários locais.']
    ], closing: 'Envie posição da parede, desenho de climatização e amostra para revisar um detalhe específico.' },
    ar: { title: 'ألواح الجدران قرب مخارج التكييف في الخليج | Luvie', description: 'راجع تدفق الهواء والرطوبة المخفية وإمكانية الصيانة قبل تركيب ألواح ديكور بجوار مخارج التكييف في الفنادق والمتاجر.', heading: 'هل يمكن تركيب ألواح ديكور بجوار مخرج تكييف في الخليج؟', lead: 'قد يبدو الجدار المجاور لمخرج التكييف جيداً لكنه يصعب صيانته إذا لم تُدرس الرطوبة والتسربات وإمكانية الوصول. القرار لا يعتمد على وصف المادة بأنها مقاومة للماء، بل على تفاصيل الجدار والهواء والصيانة في الغرفة المحددة.', answer: 'لا يُتخذ قرار التركيب إلا بعد مراجعة تدفق الهواء وخطر التكاثف وحالة القاعدة والمسافات وإمكانية الوصول لمخرج التكييف والنظام المحددين.', sections: [
      ['ابحث عن مصدر الرطوبة', 'حدّد ما إذا كان الجدار خارجياً أو داخلياً مبرداً أو بجوار أنبوب صرف التكاثف. افحص البقع والروائح والتسربات السابقة. تتناول إرشادات وكالة حماية البيئة الأمريكية EPA الرطوبة باعتبارها مسألة تصميم وصيانة للمبنى، ولا تمنح شهادة لأي لوح. السطح القابل للتنظيف لا يصلح جداراً مبتلاً أو أنبوباً مسرباً.'],
      ['ارسم مخرج الهواء واللوح في تفصيل واحد', 'بيّن فتحة الدفع ومسار العودة والأسطح الباردة والفواصل والتثبيت وفتحة الصيانة القابلة للفك. تأكد أن التشطيب لا يعيق الهواء أو الوصول إلى المعدات. يراجع مهندس التكييف مواضع التقاء الهواء الرطب بالسطح البارد وإمكانية جفاف التجميع. لا تنقل مسافات مشروع آخر من دون تعليمات الجهاز والموافقة المحلية.'],
      ['اختبر التشطيب أثناء تشغيل التكييف', 'اطلب رمز الطراز وتعليمات تركيبه الحالية. نفّذ نموذجاً صغيراً بزاوية وحافة وفتحة صيانة. راقبه مع تشغيل التكييف وافحص القاعدة قبل إغلاق الجدار. يجب فحص التنظيف والتثبيت ومتطلبات الحريق بصورة مستقلة للطراز نفسه؛ الصورة لا تثبت المطابقة.'],
      ['سلّم خطة صيانة واضحة', 'حدّد من يفحص المخرج ومصرف التكاثف وخلفية الجدار وكيف تُفتح فتحة الخدمة دون إتلاف التشطيب. احتفظ بالرسومات ورمز العينة وصور الطبقات المخفية. في سلسلة فنادق أو متاجر اختبر تفصيلاً واحداً معتمداً قبل تكراره في مواقع عديدة.']
    ], closing: 'أرسل موضع الجدار ورسم التكييف والعينة المختارة لمراجعة تفصيل مناسب للطراز.' }
  },
  {
    file: 'uzbekistan-spc-flooring-concrete-slab-moisture-check.html', image: 'spc-slab-moisture-20261007.svg', product: '/products/spc-flooring.html', catalog: '/assets/catalogs/spc-flooring-catalog.pdf', source: 'https://www.epa.gov/indoor-air-quality-iaq/moisture-control-guidance-building-design-construction-and-maintenance-0', sourceName: 'U.S. EPA moisture-control guidance', related: ['south-america-wall-panel-colour-sample-lighting.html', 'gulf-wall-panels-near-air-conditioning-diffusers.html', 'spc-flooring-distributor-spec-guide.html', 'uzbekistan-wall-panels-winter-delivery.html'],
    en: { title: 'SPC Flooring Over Concrete in Uzbekistan | Luvie', description: 'Before installing SPC flooring over a concrete slab in Uzbekistan, document moisture, flatness, room conditions and the exact product installation limits.', heading: 'Can SPC flooring be laid over a new concrete slab in Uzbekistan?', lead: 'A floor may look dry while moisture remains within the slab. For an importer or project buyer, the costliest mistake is approving flooring by appearance alone, especially when construction heating and occupancy schedules change. The correct answer depends on the slab test and the installation requirements for the exact SPC model.', answer: 'Possibly, but not until the slab has been assessed by an appropriate moisture method and meets the exact flooring, underlay and adhesive instructions for the project.', sections: [
      ['Record what floor is actually present', 'Separate a new slab from an old slab, a ground-bearing floor and an upper-floor screed. Note its age, any curing compounds, cracks, repairs and waterproofing or vapor-control layers. Ask the contractor for the slab build-up and previous test records. A smooth surface is not proof that moisture below the top layer is acceptable.'],
      ['Measure moisture before covering it', 'The U.S. EPA moisture-control guidance discusses concrete-slab moisture testing before resilient floor coverings and warns that covering wet assemblies can cause failures. This is general building guidance, not a numerical limit for Luvie SPC. Select the test method and acceptance criteria required by the current product instructions and project specification; record location, conditions, date and results. Do not borrow a limit from another brand.'],
      ['Check flatness, movement and room conditions', 'Inspect uneven areas, joints, cracks and edges; follow the exact leveling and expansion guidance for the chosen floor. Check that the space and material storage conditions meet the manufacturer’s current instructions before opening cartons. If underfloor heating is planned, ask for written compatibility, start-up procedure and temperature limits for that SKU rather than assuming every SPC product behaves alike.'],
      ['Approve a test area and preserve evidence', 'Install a small area with the specified underlay, perimeter gap, transition and door detail. Inspect it under normal lighting and traffic before authorizing the full floor. Save the slab readings, carton codes, photos and approved sample. If the slab fails the specified checks, resolve the moisture source and retest before covering it; no decorative finish can repair an unresolved wet base.']
    ], closing: 'Send the SPC model, slab build-up, moisture-test record and heating plan to request current model-specific installation information.' },
    es: { title: 'SPC sobre hormigón en Uzbekistán: humedad | Luvie', description: 'Antes de instalar suelo SPC sobre hormigón, documente humedad, planeidad, condiciones interiores y límites del producto exacto.', heading: '¿Se puede instalar suelo SPC sobre una losa nueva en Uzbekistán?', lead: 'Un suelo puede parecer seco mientras queda humedad dentro de la losa. Para un importador, aprobarlo solo por su aspecto puede crear problemas cuando cambian calefacción y calendario de obra. La respuesta depende de las mediciones y de las instrucciones del modelo SPC exacto.', answer: 'Es posible, pero primero se debe evaluar la humedad con un método adecuado y cumplir las instrucciones del suelo, la base y el adhesivo previstos.', sections: [
      ['Identifique la losa real', 'Distinga losa nueva, losa antigua, suelo apoyado en terreno y recrecido de planta alta. Anote edad, productos de curado, grietas, reparaciones y capas de control de vapor. Solicite composición y ensayos anteriores al contratista. Una superficie lisa no demuestra que la humedad interna sea aceptable.'],
      ['Mida la humedad antes de cubrirla', 'La guía de la EPA analiza pruebas de humedad en losas antes de colocar revestimientos resilientes y advierte de fallos al cubrir conjuntos mojados. Es orientación general, no un límite numérico para SPC Luvie. Use el método y criterio exigidos por las instrucciones actuales y el proyecto; registre lugar, condiciones, fecha y resultados. No copie el límite de otra marca.'],
      ['Revise planeidad, movimiento y ambiente', 'Inspeccione desniveles, juntas, grietas y bordes; siga las indicaciones exactas sobre nivelación y dilatación. Compruebe que almacenamiento y sala cumplan las condiciones actuales antes de abrir cartones. Si habrá calefacción radiante, pida compatibilidad escrita, secuencia de puesta en marcha y límite térmico para ese modelo.'],
      ['Apruebe una zona de prueba', 'Instale una pequeña superficie con base, junta perimetral, transición y puerta especificadas. Evalúela con luz y uso normales antes de autorizar toda la obra. Conserve lecturas, códigos de cartón, fotos y muestra. Si la losa no supera los controles, resuelva la fuente de humedad y repita la prueba antes de cubrirla.']
    ], closing: 'Envíe modelo SPC, composición de losa, pruebas de humedad y plan de calefacción para pedir instrucciones actuales.' },
    'pt-br': { title: 'Piso SPC sobre concreto no Uzbequistão | Luvie', description: 'Antes de instalar piso SPC sobre laje de concreto, registre umidade, planicidade, condições do ambiente e limites do modelo exato.', heading: 'É possível instalar piso SPC sobre laje nova no Uzbequistão?', lead: 'Um piso pode parecer seco enquanto ainda há umidade no interior da laje. Para importadores e compradores de obras, aprovar só pela aparência é arriscado, sobretudo quando aquecimento e cronograma mudam. A resposta depende dos ensaios e das instruções do SPC escolhido.', answer: 'Talvez, mas apenas depois de avaliar a umidade pelo método apropriado e cumprir as instruções do piso, manta e adesivo previstos.', sections: [
      ['Identifique a base real', 'Separe laje nova, laje antiga, piso sobre o solo e contrapiso de andar superior. Registre idade, cura, fissuras, reparos e camadas de controle de vapor. Peça ao construtor o desenho da base e ensaios anteriores. Superfície lisa não prova que a umidade interna está aceitável.'],
      ['Meça a umidade antes de cobrir', 'A orientação da EPA discute testes de umidade de lajes antes de revestimentos resilientes e alerta para falhas quando materiais úmidos são cobertos. É orientação geral, não limite numérico para SPC Luvie. Use método e critério das instruções atuais e do projeto; registre ponto, condições, data e resultado. Não copie o limite de outra marca.'],
      ['Confira planicidade, movimentação e ambiente', 'Examine desníveis, juntas, fissuras e bordas; siga a orientação exata de regularização e dilatação. Verifique as condições de armazenamento e da sala antes de abrir caixas. Se houver piso aquecido, solicite compatibilidade por escrito, partida do sistema e limite de temperatura para o SKU.'],
      ['Aprove uma área de teste', 'Instale pequena área com manta, folga perimetral, transição e porta conforme especificação. Avalie com luz e uso normais antes de liberar a obra inteira. Guarde leituras, códigos das caixas, fotos e amostra aprovada. Se a laje falhar nos controles, resolva a origem da umidade e teste novamente antes de cobrir.']
    ], closing: 'Envie modelo SPC, estrutura da laje, resultados de umidade e plano de aquecimento para solicitar informações atuais.' },
    ar: { title: 'أرضيات SPC فوق الخرسانة في أوزبكستان | Luvie', description: 'افحص رطوبة البلاطة الخرسانية واستواءها وظروف المكان وحدود تركيب طراز SPC المحدد قبل بدء العمل.', heading: 'هل يمكن تركيب أرضيات SPC فوق بلاطة خرسانية جديدة في أوزبكستان؟', lead: 'قد يبدو السطح جافاً بينما تبقى رطوبة داخل البلاطة. ويكون اعتماد الأرضية بالمظهر وحده مخاطرة للمستورد والمشروع، خصوصاً مع تغير التدفئة وبرنامج الأعمال. تعتمد الإجابة على نتائج الفحص وتعليمات طراز SPC المحدد.', answer: 'قد يكون ذلك ممكناً، لكن بعد فحص رطوبة البلاطة بطريقة مناسبة واستيفاء تعليمات الأرضية والطبقة السفلية واللاصق المحددين.', sections: [
      ['حدّد نوع القاعدة الفعلي', 'ميّز بين بلاطة جديدة وقديمة وأرضية على التربة وطبقة تسوية في طابق علوي. سجّل عمرها ومواد المعالجة والشقوق والإصلاحات وطبقات ضبط البخار. اطلب من المقاول تركيب البلاطة وسجلات الاختبار السابقة. نعومة السطح لا تثبت قبول الرطوبة داخله.'],
      ['قس الرطوبة قبل تغطية الخرسانة', 'تناقش إرشادات EPA اختبار رطوبة البلاطات قبل وضع أغطية الأرضيات المرنة وتحذر من فشل التجميعات المغطاة وهي رطبة. هذا إرشاد بناء عام، وليس حداً رقمياً لأرضية SPC من Luvie. اختر طريقة الاختبار وحد القبول وفق تعليمات الطراز الحالية ومواصفة المشروع، وسجّل الموقع والظروف والتاريخ والنتيجة. لا تنقل حد شركة أخرى.'],
      ['افحص الاستواء والحركة وظروف الغرفة', 'راجع المناطق غير المستوية والفواصل والشقوق والحواف، واتبع تعليمات التسوية والتمدد الخاصة بالطراز. تأكد أن التخزين والغرفة يطابقان التعليمات قبل فتح الصناديق. إذا كانت هناك تدفئة أرضية، اطلب موافقة مكتوبة وإجراء التشغيل وحد الحرارة المسموح لذلك المنتج بدلاً من افتراض تماثل جميع أرضيات SPC.'],
      ['اعتمد مساحة تجربة واحتفظ بالأدلة', 'ركّب مساحة صغيرة بالطبقة السفلية والفاصل المحيطي والانتقال وتفصيل الباب المحددين. راجعها تحت الإضاءة والاستخدام المعتادين قبل تعميم العمل. احتفظ بقراءات البلاطة ورموز الصناديق والصور والعينة. إذا فشلت البلاطة في الفحص، عالج مصدر الرطوبة وأعد الاختبار قبل تغطيتها.']
    ], closing: 'أرسل طراز SPC وتركيب البلاطة ونتائج الرطوبة وخطة التدفئة لطلب تعليمات التركيب الحالية.' }
  }
];
